const Default = () => (
  <div style={{ padding: '3rem 4rem' }}>
    <Chameleon />
  </div>
);

const Open = () => <CommandPalette
    open
    items={[
      { id: 'tokens', label: 'Browse tokens', description: 'Explore color, type, spacing' },
      { id: 'components', label: 'Components', description: 'View component gallery' },
      { id: 'glass', label: 'Glass Lab', description: 'Experiment with surfaces' },
      { id: 'a11y', label: 'Accessibility', description: 'WCAG + APCA audits' },
    ]}
    placeholder="Search…"
    onClose={() => undefined}
    onSelect={() => undefined} />;

const Menu = () => (
  <Dropdown
    ariaLabel="Actions"
    trigger={({ open }) => <Button variant="secondary">{open ? '▲' : '▼'} Actions</Button>}
    items={[{ value: 'edit', label: 'Edit' }, { value: 'share', label: 'Share' }, { value: 'del', label: 'Delete', disabled: true }]}
    onSelect={(v) => console.log(v)}
  />
);

const Default = () => <Footer
    brandLabel="P31 Labs"
    tagline="Sovereign, neuroinclusive interface foundation."
    legalText="MIT · built on DTCG tokens"
    columns={[
      {
        title: 'System',
        links: [{ label: 'Tokens', href: '/tokens' }, { label: 'Components', href: '/components' }],
      },
      {
        title: 'Explore',
        links: [{ label: 'Brands', href: '/brands' }, { label: 'Accessibility', href: '/a11y' }],
      },
    ]} />;

components.description:
Dialog with overlay. Escape closes; clicking the overlay closes;
focus moves into the panel on open and returns on close.
Crisis mode renders the overlay fully opaque via CSS.

